<?php
declare(strict_types=1);require_once __DIR__.'/src/auth.php';require_admin();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(($_POST['action']??'')==='add'){$s=$pdo->prepare('INSERT INTO students(student_id,username,face_image,register_date,is_active) VALUES(?,?,?,NOW(),?)');$s->execute([trim($_POST['student_id']),trim($_POST['username']),trim($_POST['face_image']??''),isset($_POST['is_active'])?1:0]);$msg='Student added successfully.';}elseif(($_POST['action']??'')==='delete'){$s=$pdo->prepare('DELETE FROM students WHERE student_id=?');$s->execute([$_POST['student_id']]);$msg='Student deleted.';}}catch(PDOException $e){$err='Student ID or Username already exists.';}}
$rows=$pdo->query('SELECT * FROM students ORDER BY register_date DESC')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Students</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link href="assets/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/partials/navbar.php';?><div class="container-fluid"><div class="row"><?php include __DIR__.'/partials/sidebar.php';?><main class="col-lg-10 p-4"><h1 class="fw-bold">Students</h1><p class="text-muted">Add and manage registered students.</p><?php if($msg):?><div class="alert alert-success"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=h($err)?></div><?php endif;?><div class="card border-0 shadow-sm mb-4"><div class="card-header bg-white"><h5>Add Student</h5></div><div class="card-body"><form method="post" class="row g-3"><input type="hidden" name="action" value="add"><div class="col-md-3"><label class="form-label">Student ID</label><input name="student_id" class="form-control" required></div><div class="col-md-3"><label class="form-label">Username</label><input name="username" class="form-control" required></div><div class="col-md-4"><label class="form-label">Face Image filename</label><input name="face_image" class="form-control" placeholder="student.jpg"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Add Student</button></div></form></div></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Student ID</th><th>Username</th><th>Face Image</th><th>Register Date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['student_id'])?></td><td><?=h($r['username'])?></td><td><?=h($r['face_image'])?></td><td><?=h($r['register_date'])?></td><td><?=$r['is_active']?'<span class="badge text-bg-success">Active</span>':'<span class="badge text-bg-secondary">Inactive</span>'?></td><td><form method="post"><input type="hidden" name="action" value="delete"><input type="hidden" name="student_id" value="<?=h($r['student_id'])?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center text-muted py-4">No student records yet.</td></tr><?php endif;?></tbody></table></div></div></main></div></div></body></html>